/// <summary>
/// MPJ_28155_SalesFinalisation 3.6.3 Sales order shipments
/// </summary>
public class METShipmentTable extends common
{
}

Method.Source:
    /// <summary>
    /// Finds a specific <c>METShipmentTable</c> record with given parameters.
    /// </summary>
    /// <param name = "_shipmentId">Id of the shipment.</param>
    /// <param name = "_forUpdate">Determines whether the record is selected for update.</param>
    /// <param name = "_concurrencyModel">Determines the concurreny model when selecting <c>METShipmentTable</c> record.</param>
    /// <returns>The record that is searched for.</returns>
    static METShipmentTable find(METShipmentId      _shipmentId,
                                 boolean            _forUpdate = false,
                                 ConcurrencyModel   _concurrencyModel = ConcurrencyModel::Auto)
    {
        METShipmentTable  shipmentTable;

        if (_shipmentId)
        {
            if (_forUpdate)
            {
                shipmentTable.selectForUpdate (_forUpdate);
                if (_concurrencyModel != ConcurrencyModel::Auto)
                {
                    shipmentTable.concurrencyModel(_concurrencyModel);
                }
            }
            shipmentTable.selectLocked(_forUpdate);

            select firstonly shipmentTable
                where shipmentTable.ShipmentId == _shipmentId;
        }

        return shipmentTable;
    }

    /// <summary>
    /// MPJ_28155_SalesFinalisation 3.7.2 Periodic task
    /// Finds a specific <c>METShipmentTable</c> record with given route parameter.
    /// </summary>
    /// <param name = "_route">Primary route of the shipment.</param>
    /// <param name = "_shipmentStatus">Status of the shipment</param>
    /// <param name = "_forUpdate">Determines whether the record is selected for update.</param>
    /// <param name = "_concurrencyModel">Determines the concurreny model when selecting <c>METShipmentTable</c> record.</param>
    /// <returns>The record that is searched for.</returns>
    static METShipmentTable findRoute(METRoute          _route,
                                      WHSShipmentStatus _shipmentStatus,
                                      boolean           _forUpdate = false,
                                      ConcurrencyModel  _concurrencyModel = ConcurrencyModel::Auto)
    {
        const str emptyString = '';
        
        METShipmentTable  shipmentTable;

        if (_route)
        {
            if (_forUpdate)
            {
                shipmentTable.selectForUpdate (_forUpdate);
                if (_concurrencyModel != ConcurrencyModel::Auto)
                {
                    shipmentTable.concurrencyModel(_concurrencyModel);
                }
            }
            shipmentTable.selectLocked(_forUpdate);

            select firstonly shipmentTable
                       where shipmentTable.PrimaryRoute == _route
                          && shipmentTable.ShipmentStatus == _shipmentStatus
                          && shipmentTable.LoadId != emptyString;
        }

        return shipmentTable;
    }

    /// <summary>
    /// MPJ_28155_SalesFinalisation 3.6.9 Post delivery note
    /// Finds a specific <c>METShipmentTable</c> record with given sales order number parameter.
    /// </summary>
    /// <param name = "_salesId">Sales order nubmer of the shipment line.</param>
    /// <param name = "_forUpdate">Determines whether the record is selected for update.</param>
    /// <param name = "_concurrencyModel">Determines the concurreny model when selecting <c>METShipmentTable</c> record.</param>
    /// <returns>The record that is searched for.</returns>
    static METShipmentTable findSalesId(SalesId            _salesId,
                                        boolean            _forUpdate = false,
                                        ConcurrencyModel   _concurrencyModel = ConcurrencyModel::Auto)
    {
        METShipmentTable  shipmentTable;
        METShipmentLine   shipmentLine;

        if (_salesId)
        {
            if (_forUpdate)
            {
                shipmentTable.selectForUpdate (_forUpdate);
                if (_concurrencyModel != ConcurrencyModel::Auto)
                {
                    shipmentTable.concurrencyModel(_concurrencyModel);
                }
            }
            shipmentTable.selectLocked(_forUpdate);

            select firstonly shipmentTable
                 exists join shipmentLine
                       where shipmentLine.ShipmentId == shipmentTable.ShipmentId
                          && shipmentLine.SalesId == _salesId;
        }

        return shipmentTable;
    }

    /// <summary>
    /// Checks if a specific <c>METShipmentTable</c> record exists.
    /// </summary>
    /// <param name = "_shipmentId">Id of the shipment.</param>
    /// <returns>True if the record exists; otherwise, false</returns>
    static boolean exist(METShipmentId _shipmentId)
    {
        if (!_shipmentId)
        {
            return false;
        }

        return (select firstonly RecId from METShipmentTable
                    where METShipmentTable.ShipmentId == _shipmentId).RecId != 0;
    }

    /// <summary>
    /// Checks if a specific <c>METShipmentTable</c> record exists for a load.
    /// </summary>
    /// <param name = "_loadId">Id of the load.</param>
    /// <returns>True if the record exists; otherwise, false</returns>
    static boolean existLoadId(METLoadId _loadId)
    {
        if (!_loadId)
        {
            return false;
        }

        return (select firstonly RecId from METShipmentTable
                    where METShipmentTable.LoadId == _loadId).RecId != 0;
    }

/// <summary>
/// Initialize fields from sales order
/// </summary>
/// <param name = "_salesTable">Updated <c>SalesTable</c> record</param>
void initFromSalesTable(SalesTable _salesTable)
{
    this.CustAccount        = _salesTable.CustAccount;
    this.SalesName          = _salesTable.SalesName;
}

    /// <summary>
    /// Transfers this shipment to a new load.
    /// Method adapted from table WHSShipmentTable
    /// </summary>
    /// <param name="_newLoadId">
    /// The <c>LoadId</c> that the shipment is transferred to.
    /// </param>
    /// <exception cref="Exception::Error">
    /// Exception is thrown if either load is already shipped or received.
    /// </exception>
    /// <exception cref="Exception::Error">
    /// Exception is thrown if the loading strategy is not valid.
    /// </exception>
    void transferShipment(METLoadId _newLoadId)
    {
        ttsbegin;
        // Transfer load to existing or new load
        this.transferLoad(this.LoadId, _newLoadId);

        // update delivery note journal Load ID if any
        this.updateCustPackingSlipJourLoadId(_newLoadId);
        ttscommit;
    }

    /// <summary>
    /// Transfers an old load to a new load.
    /// </summary>
    /// <param name = "_oldLoadId">
    /// The old load's <c>LoadId</c>.
    /// </param>
    /// <param name = "_newLoadId">
    /// The new load's <c>LoadId</c>.
    /// </param>
    /// <exception cref="Exception::Error">
    /// Exception is thrown if either load is already shipped or received.
    /// </exception>
    /// <exception cref="Exception::Error">
    /// Exception is thrown if the loading strategy is not valid.
    /// </exception>
    protected void transferLoad(METLoadId _oldLoadId, METLoadId _newLoadId)
    {
        if (_oldLoadId == _newLoadId)
        {
            return;
        }

        ttsbegin;

        this.selectForUpdate(true);
        this.LoadId = _newLoadId;
        this.update();

        ttscommit;
    }

/// <summary>
/// 3.6.3 Transfer shipment to existing load and 3.6.4 Transfer shipment to new load
/// Logic needs to update the load ID on the delivery note journal, if a delivery note is posted for the shipment.
/// </summary>
/// <param name = "_newLoadId">The new load's <c>LoadId</c>.</param>
protected void updateCustPackingSlipJourLoadId(METLoadId _newLoadId)
{
    CustPackingSlipJour custPackingSlipJour;
    ttsbegin;
    update_recordset custPackingSlipJour
             setting METLoadId = _newLoadId
               where custPackingSlipJour.METShipmentId == this.ShipmentId;
    ttscommit;
}

/// <summary>
/// 3.6.7 Multimodal dangerous goods
/// Method to return the customer group from the shipment table custom account
/// </summary>
/// <returns>Customer group from the shipment table custom account</returns>
CustGroupId custGroupId()
{
    return CustTable::find(this.CustAccount).CustGroup;
}
